"use client";

import { AlertTriangle, ArrowRight, BookOpenCheck, BriefcaseBusiness, CalendarClock, Check, CheckCircle2, Clock3, Coffee, FileCheck2, FileText, HeartHandshake, Plus, RotateCcw, Send, ShieldCheck, UserPlus, X } from "lucide-react";
import { FormEvent, useEffect, useMemo, useState } from "react";
import { useHcm } from "../../lib/hcm-context";
import {
  BenefitPlan, CandidateStage, CompensationChangeRequest, Course, EmployeeDocument, EmploymentRecord, Goal,
  HCMState, LeaveRequest, PolicyRecord, PtoPolicy, Requisition, Shift, activeBenefitEnrollments, activeCompensation,
  activePtoAssignment, appendAudit, benefitDeductionPerPayPeriod, buildOffboardingTasks, buildOnboardingTasks,
  canManageEmployee, hcmCapabilityCoverage, openHcmItems, ptoBalance, workforceMetrics,
} from "../../lib/hcm-engine";
